import { app, BrowserWindow, ipcMain, screen } from "electron";
import * as path from "path";
import * as fs from "fs";
import * as os from "os";

let mainWindow: BrowserWindow | null = null;
let initialBounds: Electron.Rectangle | null = null;
// Persist last model path in userData to survive abrupt exits
const lastModelFile = () =>
  path.join(app.getPath("userData"), "last_model.json");

// Persist per-model state (position/scale) in userData
const modelStateFile = () =>
  path.join(app.getPath("userData"), "model_state.json");

// Persist zoom settings for URLs
const zoomSettingsFile = () =>
  path.join(app.getPath("userData"), "zoom_settings.json");

function createWindow() {
  
  const primary = screen.getPrimaryDisplay();
  const area = (primary && (primary as any).workArea) ||
    (primary as any).bounds || { width: 1920, height: 1080, x: 0, y: 0 };
  const winW = 360;
  const winH = 640;
  const x = (area as any).x + (area as any).width - winW;
  const y = (area as any).y + (area as any).height - winH;

  mainWindow = new BrowserWindow({
    width: winW,
    height: winH,
    transparent: true,
    frame: false,
    alwaysOnTop: true,
    resizable: true,
    hasShadow: false,
    skipTaskbar: false,
    x,
    y,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  initialBounds = mainWindow.getBounds();

  mainWindow.loadFile(path.join(__dirname, "../public/index.html"));
  mainWindow.setIgnoreMouseEvents(false);
  mainWindow.setAlwaysOnTop(true, 'screen-saver'); // highest possible level
  mainWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  mainWindow.focus();
  mainWindow.moveTop();  
  let clickThroughActive = false;          // глобальный флаг режима
const PIN_BTN_BOUNDS = { x: 0, y: 0, w: 80, h: 32 }; // пере-заполняем динамически

/* таймер, который «дырявит» окно, но оставляет кнопку активной */
const pinAreaChecker = setInterval(() => {
  if (!mainWindow || mainWindow.isDestroyed()) { clearInterval(pinAreaChecker); return; }
  if (!clickThroughActive) return;       // обычный режим – ничего не делаем

  const win = mainWindow.getBounds();
  const { x: mx, y: my } = screen.getCursorScreenPoint();

  /* узнаём реальные координаты кнопки из рендера (раз в 100 мс) */
  mainWindow.webContents.send('request-pin-bounds'); // попросим отдать bounds
}, 100);

/* получаем bounds кнопки от рендера */
ipcMain.on('report-pin-bounds', (_e, b: {x:number,y:number,w:number,h:number}) => {
  Object.assign(PIN_BTN_BOUNDS, b);
});
const mousePoller = setInterval(() => {
  if (!mainWindow || mainWindow.isDestroyed()) {
    clearInterval(mousePoller);
    return;
  }
  if (!clickThroughActive) return;    

  syncIgnore();
}, 50);
/* каждый раз, когда курсор двигается, проверяем – над кнопкой ли он */
mainWindow.on('will-move' as any, () => syncIgnore());
mainWindow.on('will-resize' as any, () => syncIgnore());
mainWindow.hookWindowMessage(0x0200, syncIgnore); // WM_MOUSEMOVE
mainWindow.webContents.on('dom-ready', () => {
  mainWindow?.webContents.send('request-pin-bounds');
});

  // watch for events.json written by the VS Code extension
  try {
    const candidates = [
      path.join(__dirname, "../public/events.json"),
      path.join(__dirname, "../events.json"),
    ];
    for (const eventsFile of candidates) {
      if (!fs.existsSync(eventsFile)) continue;
      const emitFromFile = () => {
        try {
          const txt = fs.readFileSync(eventsFile, "utf8");
          const obj = JSON.parse(txt);

          // If this is a caret event, try to estimate screen coordinates so overlay can aim
          try {
            if (obj && obj.type === "caret") {
              const primary = screen.getPrimaryDisplay();
              const area = (primary && (primary as any).workArea) ||
                (primary as any).bounds || { x: 0, y: 0 };
              // Basic heuristics — these can be tuned by users
              const fontSize = Number(obj.fontSize) || 14;
              const lineHeight = fontSize * 1.25; // px
              const charWidth = fontSize * 0.6; // px
              // Approximate editor top-left within work area
              const editorLeft = (area as any).x + 40; // assume some left margin / window chrome
              const editorTop = (area as any).y + 60; // assume some top chrome (title bar, tabs)
              // Gutter (line numbers, folding) width
              const gutter = 56;
              const visibleStart =
                typeof obj.visibleStart === "number"
                  ? obj.visibleStart
                  : obj.line;
              const rowOffset =
                (typeof obj.line === "number" ? obj.line : 0) - visibleStart;
              const caretX =
                editorLeft +
                gutter +
                (typeof obj.character === "number" ? obj.character : 0) *
                  charWidth;
              const caretY =
                editorTop + rowOffset * lineHeight + lineHeight / 2;
              obj.screenX = Math.round(caretX);
              obj.screenY = Math.round(caretY);
              // include some debug metadata
              obj._caretMapping = {
                editorLeft,
                editorTop,
                gutter,
                lineHeight,
                charWidth,
              };
            }
          } catch (e) {}

          if (mainWindow && !mainWindow.isDestroyed())
            mainWindow.webContents.send("overlay-event", obj);
        } catch {}
      };
      // initial read
      emitFromFile();
      // watch for changes
      fs.watch(eventsFile, { persistent: false }, emitFromFile);
      break; // bind to first existing
    }
  } catch (e) {
    console.warn("Events watcher failed", e);
  }
  function syncIgnore() {
  if (!mainWindow || mainWindow.isDestroyed() || !clickThroughActive) return;

  const { x: wx, y: wy } = mainWindow.getBounds();
  const { x: mx, y: my } = screen.getCursorScreenPoint();
  const { x, y, w, h } = PIN_BTN_BOUNDS;

  const overBtn =
    mx >= wx + x && mx <= wx + x + w &&
    my >= wy + y && my <= wy + y + h;

  mainWindow.setIgnoreMouseEvents(!overBtn, { forward: true });
}
  // IPC handlers
ipcMain.handle("overlay-toggle-click-through", (_e, enabled: boolean) => {
  if (!mainWindow || mainWindow.isDestroyed()) return false;

  clickThroughActive = Boolean(enabled);
  mainWindow.setIgnoreMouseEvents(clickThroughActive, { forward: true });
  mainWindow.webContents.send('ui-mode', clickThroughActive ? 'hidden' : 'normal');
  return true;
});

  ipcMain.on("overlay-close", () => {
    if (mainWindow) mainWindow.close();
  });

  ipcMain.on("overlay-set-opacity", (_event, value: number | string) => {
    if (mainWindow) mainWindow.setOpacity(Number(value));
  });
  ipcMain.on("overlay-open-devtools", () => {
    if (mainWindow) mainWindow.webContents.openDevTools({ mode: "right" });
  });

ipcMain.on("overlay-enter-fullscreen", () => {
  if (!mainWindow) return;
  try { initialBounds = mainWindow.getBounds(); } catch {}
  const { workArea } = screen.getPrimaryDisplay();   // ← берём рабочую область
  mainWindow.setBounds(workArea, false);             // на весь экран без панели
});

ipcMain.on("overlay-exit-fullscreen", () => {
  if (!mainWindow || !initialBounds) return;
  mainWindow.setBounds(initialBounds, false);
});

  // Persist last model via filesystem (sync writes are fine for small JSON)
  ipcMain.on("overlay-save-last-model", (_ev, url: string) => {
    try {
      const file = lastModelFile();
      const dir = path.dirname(file);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(file, JSON.stringify({ url }), { encoding: "utf8" });
    } catch {}
  });
  ipcMain.handle("overlay-get-last-model", () => {
    try {
      const file = lastModelFile();
      if (!fs.existsSync(file)) return null;
      const t = fs.readFileSync(file, "utf8");
      const j = JSON.parse(t);
      return (j && j.url) || null;
    } catch {
      return null;
    }
  });

  // Save/Load model state (x, y, scale) per model URL
  ipcMain.on(
    "overlay-save-model-state",
    (_ev, payload: { url: string; x: number; y: number; scale: number }) => {
      try {
        if (!payload || !payload.url) return;
        const file = modelStateFile();
        const dir = path.dirname(file);
        if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
        let map: Record<string, any> = {};
        try {
          if (fs.existsSync(file)) {
            const txt = fs.readFileSync(file, "utf8");
            map = JSON.parse(txt) || {};
          }
        } catch {}
        map[payload.url] = {
          x: Number(payload.x) || 0,
          y: Number(payload.y) || 0,
          scale: Number(payload.scale) || 1,
          savedAt: Date.now(),
        };
        fs.writeFileSync(file, JSON.stringify(map), { encoding: "utf8" });
      } catch {}
    }
  );
  ipcMain.handle("overlay-get-model-state", (_ev, url: string) => {
    try {
      if (!url) return null;
      const file = modelStateFile();
      if (!fs.existsSync(file)) return null;
      const txt = fs.readFileSync(file, "utf8");
      const map = JSON.parse(txt) || {};
      const s = map[url];
      if (!s) return null;
      return {
        x: Number(s.x) || 0,
        y: Number(s.y) || 0,
        scale: Number(s.scale) || 1,
      };
    } catch {
      return null;
    }
  });

  // Set zoom factor for current window
  ipcMain.handle(
    "overlay-set-zoom-factor",
    async (_ev, zoomFactor: number = 1.0) => {
      try {
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.setZoomFactor(zoomFactor);
          return true;
        }
        return false;
      } catch (error) {
        console.error("Failed to set zoom factor:", error);
        return false;
      }
    }
  );

  // Save zoom settings for URLs
  ipcMain.on(
    "overlay-save-zoom-setting",
    (_ev, payload: { url: string; zoomFactor: number }) => {
      try {
        if (!payload || !payload.url) return;
        const file = zoomSettingsFile();
        const dir = path.dirname(file);
        if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
        let map: Record<string, any> = {};
        try {
          if (fs.existsSync(file)) {
            const txt = fs.readFileSync(file, "utf8");
            map = JSON.parse(txt) || {};
          }
        } catch {}
        map[payload.url] = {
          zoomFactor: Number(payload.zoomFactor) || 1.0,
          savedAt: Date.now(),
        };
        fs.writeFileSync(file, JSON.stringify(map), { encoding: "utf8" });
      } catch {}
    }
  );

  // Get zoom settings for URL
  ipcMain.handle("overlay-get-zoom-setting", (_ev, url: string) => {
    try {
      if (!url) return 1.0; // Default zoom factor
      const file = zoomSettingsFile();
      if (!fs.existsSync(file)) return 1.0;
      const txt = fs.readFileSync(file, "utf8");
      const map = JSON.parse(txt) || {};
      const setting = map[url];
      if (!setting) return 1.0;
      return Number(setting.zoomFactor) || 1.0;
    } catch {
      return 1.0;
    }
  });
}

app.whenReady().then(() => {
  createWindow();

  app.on("activate", function () {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });

  // Watchdog: if VS Code parent PID is provided and exits, quit overlay
  try {
    const ppidStr = process.env.VSCODE_PARENT_PID || "";
    const ppid = Number(ppidStr);
    if (ppid && Number.isFinite(ppid)) {
      const interval = setInterval(() => {
        try {
          process.kill(ppid, 0);
          // parent alive
        } catch {
          try {
            clearInterval(interval);
          } catch {}
          try {
            app.quit();
          } catch {}
        }
      }, 1500);
      app.once("before-quit", () => {
        try {
          clearInterval(interval);
        } catch {}
      });
    }
  } catch {}
});

app.on("window-all-closed", function () {
  if (process.platform !== "darwin") app.quit();
});
